contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We will attempt to call lockInGuess with a provided hash and 1 ether.
    // Parameters:
    // - bytes32 h: the guess hash to lock in
    // - uint amount: the ether to send with the call (we will require amount == 1 ether to be a valid attempt)
    function run(bytes32 h, uint amount) public payable {
        require(address(this).balance >= amount);

        // Read mapping for this contract's address before calling lockInGuess
        (uint beforeBlock, bytes32 beforeGuess) = c.guesses(address(this));

        bool reverted;
        // Attempt to call lockInGuess with specified amount
        try c.lockInGuess{value: amount}(h) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read mapping after the attempt
        (uint afterBlock, bytes32 afterGuess) = c.guesses(address(this));

        // General rule asserted:
        // If the call did not revert, then afterGuess equals h and afterBlock equals block.number + 1 (as set inside lockInGuess).
        // If the call reverted, then the stored block must remain 0 (unchanged from initial zero) — i.e., afterBlock == beforeBlock and beforeBlock == 0.
        // We express this as a single assert combining both cases.
        assert(
            (!reverted && afterGuess == h && afterBlock == block.number + 1)
            || (reverted && beforeBlock == 0 && afterBlock == beforeBlock)
        );
    }

    receive() external payable {}
}

