contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    // We take parameters to drive calls: hash to lock, amounts for lock (must be 1 ether),
    // and a flag whether to attempt settle afterwards.
    function run(bytes32 h, uint lockAmount, bool doSettle) public payable {
        // require we have enough balance to forward the requested amount
        require(address(this).balance >= lockAmount);
        // precondition: lockAmount must be 1 ether for lockInGuess to succeed
        // but we let the caller choose so we can observe both success and revert cases

        // Read before-state: address(c).balance and the auto-generated getter for guesses
        // Note: guesses is a public mapping => getter guesses(address) returns (uint, bytes32)
        (uint beforeBlock, bytes32 beforeGuess) = c.guesses(address(this));
        uint beforeBalanceC = address(c).balance;

        bool lockedReverted;
        try c.lockInGuess{value: lockAmount}(h) {
            lockedReverted = false;
        } catch {
            lockedReverted = true;
        }

        // After attempt to lock, read state
        (uint afterBlock, bytes32 afterGuess) = c.guesses(address(this));
        uint afterBalanceC = address(c).balance;

        // Optionally attempt to settle (could revert if no guess or not enough blocks passed)
        bool settledReverted;
        if (doSettle) {
            try c.settle() {
                settledReverted = false;
            } catch {
                settledReverted = true;
            }
        } else {
            settledReverted = false;
        }

        // Now assert a general invariant about effects of lockInGuess and settle:
        // - If lockInGuess did not revert, then beforeBlock must have been 0,
        //   afterBlock must equal block.number + 1 (as stored by lockInGuess), and afterGuess == h,
        //   and c's balance must have increased by lockAmount.
        // - If lockInGuess reverted, then state must be unchanged (block and guess for this address and c balance).
        // - Additionally, regardless of settle outcome, c's balance must never decrease by more than 2 ether
        //   compared to beforeBalanceC (settle can pay at most 2 ether).

        bool invariant;

        bool balanceLimited = (beforeBalanceC >= afterBalanceC ? (beforeBalanceC - afterBalanceC) <= 2 ether : true);

        if (!lockedReverted) {
            // lock succeeded
            invariant = (beforeBlock == 0
                         && afterBlock == block.number + 1
                         && afterGuess == h
                         && afterBalanceC == beforeBalanceC + lockAmount
                         && balanceLimited);
        } else {
            // lock reverted -> no change to guesses and balance
            invariant = (beforeBlock == afterBlock
                         && beforeGuess == afterGuess
                         && beforeBalanceC == afterBalanceC
                         && balanceLimited);
        }

        assert(invariant);
    }

    // Allow the contract to receive ether when c.transfer is invoked during settle
    receive() external payable {}
}

contract InvMutTest {
