        c = _c;
    }

    // We take a hash, an amount to send to lockInGuess, and a flag whether to call settle.
    function run(bytes32 h, uint lockAmount, bool doSettle) public payable {
        // ensure this test contract has enough balance to forward lockAmount
        require(address(this).balance >= lockAmount);

        uint beforeBalanceC = address(c).balance;

        // Attempt to call lockInGuess with the provided amount and record whether it reverted
        bool lockReverted;
        try c.lockInGuess{value: lockAmount}(h) {
            lockReverted = false;
        } catch {
            lockReverted = true;
        }

        uint afterLockBalanceC = address(c).balance;

        // Optionally attempt to settle and record whether it reverted
        bool settleReverted = false;
        if (doSettle) {
            try c.settle() {
                settleReverted = false;
            } catch {
                settleReverted = true;
            }
        }

        uint afterAllBalanceC = address(c).balance;

        // General invariant to assert:
        // - If lockInGuess succeeded (did not revert) then c's balance increased by exactly lockAmount.
        // - If lockInGuess reverted then c's balance did not change because of that call.
        // - In any case, after optionally calling settle, c's balance has decreased by at most 2 ether
        //   compared to the balance just after lock attempt (settle can pay at most 2 ether out).

        bool lockEffectCorrect;
        if (!lockReverted) {
            // If it didn't revert, lockAmount must have been accepted by c (balance increased by lockAmount)
            lockEffectCorrect = (afterLockBalanceC == beforeBalanceC + lockAmount);
        } else {
            // If it reverted, balance should be unchanged
            lockEffectCorrect = (afterLockBalanceC == beforeBalanceC);
        }

        // settle can at most transfer out 2 ether in a single settle call; ensure the drop from afterLockBalanceC
        // to afterAllBalanceC is no more than 2 ether (allowing increases as well, though increases shouldn't occur here)
        bool settleBounded = (afterLockBalanceC >= afterAllBalanceC) ? (afterLockBalanceC - afterAllBalanceC) <= 2 ether : true;

        assert(lockEffectCorrect && settleBounded);
    }

    receive() external payable {}
}

