    // We take two parameters: a candidate hash to lock, and the amount to send when locking (must be 1 ether to succeed).
    // We also take a boolean `doSecondLock` to attempt a second lockInGuess which should revert if the first succeeded.
    function run(bytes32 hash, uint256 amount, bool doSecondLock) public payable {
        require(address(this).balance >= amount);
        // Ensure we can fund the initial contract constructor requirement: c was deployed with 1 ether by the harness per spec.

        // Attempt to lock in a guess with provided amount
        bool firstReverted;
        try c.lockInGuess{value: amount}(hash) {
            firstReverted = false;
        } catch {
            firstReverted = true;
        }

        // Read observable state: c's balance and this contract's balance after attempt
        uint256 balC_after_first = address(c).balance;
        uint256 balThis_after_first = address(this).balance;

        // If first call succeeded, then a second lockInGuess without settling by same address should revert because mapping.block != 0
        bool secondReverted = false;
        if (doSecondLock) {
            try c.lockInGuess{value: amount}(hash) {
                secondReverted = false;
            } catch {
                secondReverted = true;
            }
        }

        // We assert the general rule:
        // - If the first lock call reverted, then c's balance shouldn't have increased by amount.
