contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // Params:
    // - uint lockValue: wei to send when calling lockInGuess
    // - bytes32 h: hash to pass to lockInGuess
    // We cannot access internal mapping guesses directly, so we observe effects via balances and settle behavior.
    function run(uint lockValue, bytes32 h) public payable {
        require(address(this).balance >= lockValue);

        // record balances before attempting lock
        uint beforeC = address(c).balance;
        uint beforeThis = address(this).balance;

        // attempt lockInGuess and record whether it reverted
        bool lockReverted;
        try c.lockInGuess{value: lockValue}(h) {
            lockReverted = false;
        } catch {
            lockReverted = true;
        }

        // balances after lock attempt
        uint afterC = address(c).balance;
        uint afterThis = address(this).balance;

        // Now attempt to call settle and see if it can transfer 2 ether to this contract.
        // settle may revert if there is no active guess or block conditions not met; capture revert and balance change.
        bool settleReverted;
        uint beforeSettleThis = address(this).balance;
        try c.settle() {
            settleReverted = false;
        } catch {
            settleReverted = true;
        }
        uint afterSettleThis = address(this).balance;

        // General invariant asserted:
        // - If lock reverted then balances are unchanged and settle cannot have increased this contract's balance (no unexpected payout).
        // - If lock succeeded then c's balance increased exactly by lockValue and this contract's balance decreased by lockValue; any subsequent successful settle can at most increase this contract's balance by 2 ether (the intended payout), and if settle increased the balance by 2 ether then c's balance must have decreased by 2 ether compared to after lock.
        assert(
            (
                lockReverted
                && afterC == beforeC
                && afterThis == beforeThis
                && (afterSettleThis == beforeSettleThis) // no payout if lockReverted
            )
            ||
            (
                !lockReverted
                && afterC == beforeC + lockValue
                && afterThis == beforeThis - lockValue
                && (
                    // if settle did not increase our balance, it's allowed
                    (afterSettleThis == beforeSettleThis)
                    // or if settle succeeded and increased by 2 ether, then c lost 2 ether
                    || (
                        !settleReverted
                        && afterSettleThis == beforeSettleThis + 2 ether
                        && address(c).balance + 2 ether == afterC
                    )
                )
            )
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    // single public function taking inputs: amount to send and a guess hash
    function run(uint256 amount, bytes32 h) public payable {
        // require we have enough balance to forward the requested amount
        require(address(this).balance >= amount);
        // read pre-state
        uint256 before_c_balance = address(c).balance;
        // read public getter for guesses[msg.sender].block via auto-getter: guesses(address) returns (uint256, bytes32)
        (uint256 before_block, bytes32 before_guess) = c.guesses(address(this));

        bool reverted;
        // attempt to call lockInGuess with provided amount and hash
        try c.lockInGuess{value: amount}(h) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 after_c_balance = address(c).balance;
        (uint256 after_block, bytes32 after_guess) = c.guesses(address(this));

        // General rule:
        // If the call succeeded (did not revert) then it must have been with exactly 1 ether,
        // and the contract's stored block must now equal block.number + 1 and the contract's balance increased by 1 ether.
        // If the call reverted then nothing changed: stored block remains equal to before_block and balance unchanged.
        assert(
            reverted
            ? (after_block == before_block && after_guess == before_guess && after_c_balance == before_c_balance)
            : (
                // call succeeded
                amount == 1 ether &&
                // stored block should be set to current block number + 1
                after_block == block.number + 1 &&
                // guess stored should equal provided hash
                after_guess == h &&
                // contract balance must have increased by 1 ether
                after_c_balance == before_c_balance + 1 ether
            )
        );
    }

    // accept ether so this test can forward funds
    receive() external payable {}
}
